import{_ as t,o as r,c as a,ag as i}from"./chunks/framework.ClUfsdUo.js";const g=JSON.parse('{"title":"What is react-tree-grid?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),o={name:"guide/index.md"};function d(s,e,n,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="what-is-react-tree-grid" tabindex="-1">What is react-tree-grid? <a class="header-anchor" href="#what-is-react-tree-grid" aria-label="Permalink to &quot;What is react-tree-grid?&quot;">​</a></h1><p><strong>react-tree-grid</strong> is an open-source, high-performance component library for React 18+ that provides three components: <code>Grid</code>, <code>Tree</code>, and <code>TreeGrid</code>.</p><p>It is a drop-in alternative to <a href="https://dhtmlx.com/docs/products/dhtmlxTreeGrid/" target="_blank" rel="noreferrer">DHTMLX TreeGrid</a> — replicating its API surface while being fully open-source, zero-dependency, and TypeScript-first.</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Use when…</th></tr></thead><tbody><tr><td><code>Grid</code></td><td>You need a flat tabular data grid with sorting, filtering, editing, and selection</td></tr><tr><td><code>Tree</code></td><td>You need a hierarchical file-tree style list with expand/collapse and checkboxes</td></tr><tr><td><code>TreeGrid</code></td><td>You need a data grid where rows have parent–child relationships shown in a tree column</td></tr></tbody></table><h2 id="key-features" tabindex="-1">Key features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key features&quot;">​</a></h2><ul><li><strong>Virtual scrolling</strong> — renders only visible rows, handles 100,000+ rows smoothly</li><li><strong>Inline editing</strong> — <code>input</code>, <code>select</code>, <code>checkbox</code>, <code>combo</code>, <code>datePicker</code> editor types</li><li><strong>Sorting &amp; filtering</strong> — per-column header filters with <code>inputFilter</code>, <code>selectFilter</code>, <code>comboFilter</code></li><li><strong>Drag and drop</strong> — reorder rows and columns; tree drag between nodes</li><li><strong>Column operations</strong> — resize, reorder, freeze, hide/show, auto-width</li><li><strong>Theming</strong> — light/dark presets + full CSS custom property overrides</li><li><strong>TypeScript</strong> — all props, events, and types fully typed</li><li><strong>Zero dependencies</strong> — React 18+ is the only peer dependency</li></ul><h2 id="package" tabindex="-1">Package <a class="header-anchor" href="#package" aria-label="Permalink to &quot;Package&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @itsmemyk/react-tree-grid</span></span></code></pre></div><p>The package ships ES modules and CJS with full TypeScript declarations. Sub-path exports allow tree-shaking individual components.</p>',10)])])}const u=t(o,[["render",d]]);export{g as __pageData,u as default};
